//! Shared test helpers: build requests, run the real engine, and run the
//! independent naive oracle. Test answers come from the oracle and from
//! hand-computed constants — never generated by the engine under test.
#![allow(dead_code)]
use leapfrog_triejoin::domain::{Datum, LogicalType, NullPolicy};
use leapfrog_triejoin::join::{execute, naive};
use leapfrog_triejoin::query::{compile, JoinRequest, RelationInput};
use leapfrog_triejoin::resource::Catalog;
use leapfrog_triejoin::{resolve_inputs, AppState, ServerConfig};

pub fn col(name: &str, ty: LogicalType) -> leapfrog_triejoin::batch::ColumnSchema {
    leapfrog_triejoin::batch::ColumnSchema::new(name, ty)
}

pub fn ints(xs: &[i64]) -> Vec<Datum> {
    xs.iter().map(|v| Datum::Int(*v)).collect()
}

pub fn rel(name: &str, cols: &[(&str, LogicalType)], rows: Vec<Vec<Datum>>) -> RelationInput {
    RelationInput {
        name: name.to_string(),
        schema: cols.iter().map(|(n, t)| col(n, *t)).collect(),
        rows,
    }
}

pub fn req(relations: Vec<RelationInput>) -> JoinRequest {
    JoinRequest {
        relations,
        fixtures: vec![],
        select: None,
        limit: 100,
        cursor: None,
        null_policy: NullPolicy::Reject,
        request_id: None,
    }
}

pub struct Case {
    pub plan: leapfrog_triejoin::Plan,
    pub inputs: Vec<RelationInput>,
    pub request: JoinRequest,
}

pub fn compile_case(mut request: JoinRequest) -> Case {
    let catalog = Catalog::new();
    let state = AppState::new(ServerConfig::default(), catalog);
    let inputs = resolve_inputs(&request, state.catalog.try_read().unwrap().entries()).unwrap();
    let plan = compile(inputs.clone(), &request).unwrap();
    request.limit = request.effective_limit();
    Case {
        plan,
        inputs,
        request,
    }
}

/// Engine output as `(values, multiplicity)` pairs.
pub fn engine_rows(
    case: &Case,
    limit: u64,
    cursor: Option<String>,
) -> leapfrog_triejoin::join::ExecOutput {
    let after = cursor.map(|t| {
        let types: Vec<LogicalType> = case
            .plan
            .select
            .iter()
            .map(|a| {
                case.plan.output_types[case
                    .plan
                    .output_attributes
                    .iter()
                    .position(|x| x == a)
                    .unwrap()]
            })
            .collect();
        leapfrog_triejoin::join::decode_after(&t, &types).unwrap()
    });
    execute(&case.plan, limit, after)
}

/// Independent naive oracle rows for the same request.
pub fn oracle_rows(case: &Case) -> Vec<naive::NaiveRow> {
    naive::naive_join(&case.inputs, &case.plan.select, case.request.null_policy)
        .unwrap()
        .rows
}

pub fn as_ints(row: &[Datum]) -> Vec<i64> {
    row.iter()
        .map(|d| match d {
            Datum::Int(i) => *i,
            other => panic!("expected int, got {other:?}"),
        })
        .collect()
}

/// Complete directed edges of K_n as (i,j),(j,i) pairs.
pub fn complete_edges(n: i64) -> Vec<Vec<Datum>> {
    let mut out = Vec::new();
    for i in 0..n {
        for j in 0..n {
            if i != j {
                out.push(ints(&[i, j]));
            }
        }
    }
    out
}
